class AccessControlMatrix {
    public String publicNote = "Visible Everywhere";
    String packageNote = "Visible in Same Package";
    private String secretVaultCode = "TOP_SECRET_987";

    // Private helper method - internal class mechanics
    private void logAudit(String action) {
        System.out.println("[INTERNAL AUDIT] " + action);
    }

    // Public interface method
    public void revealSecretWithAuth(boolean isAuthorized) {
        if (isAuthorized) {
            logAudit("Access granted to secret.");
            System.out.println("Vault Secret: " + secretVaultCode);
        } else {
            logAudit("Unauthorized access denied.");
            System.out.println("Access Denied!");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        AccessControlMatrix matrix = new AccessControlMatrix();

        // Reading public and default fields
        System.out.println("Public: " + matrix.publicNote);
        System.out.println("Package: " + matrix.packageNote);

        // Cannot access privateVar directly: matrix.secretVaultCode -> Compile Error!
        // Interacting via public controlled method
        matrix.revealSecretWithAuth(false);
        matrix.revealSecretWithAuth(true);
    }
}

