class OrderProcessor {
    private double orderAmount;
    private String customerCountry;

    public OrderProcessor(double amount, String country) {
        this.orderAmount = amount;
        this.customerCountry = country;
    }

    // Private helper: internal tax calculation not exposed to client
    private double computeTaxRate() {
        if ("USA".equalsIgnoreCase(customerCountry)) {
            return 0.08;
        } else if ("Germany".equalsIgnoreCase(customerCountry)) {
            return 0.19;
        } else {
            return 0.05;
        }
    }

    // Public interface: Clean, simple method for callers
    public double calculateTotalInvoice() {
        double tax = orderAmount * computeTaxRate();
        return orderAmount + tax;
    }
}

public class Main {
    public static void main(String[] args) {
        OrderProcessor order = new OrderProcessor(100.0, "USA");
        System.out.println("Invoice Total: $" + order.calculateTotalInvoice());
    }
}

