class UserAccount {
    public String username;
    private String passwordHash;

    public UserAccount(String username, String pass) {
        this.username = username;
        this.passwordHash = pass;
    }

    public boolean checkPassword(String attempt) {
        return passwordHash != null && passwordHash.equals(attempt);
    }
}

public class Main {
    public static void main(String[] args) {
        UserAccount acc = new UserAccount("dev_user", "secret123");
        System.out.println("Auth result: " + acc.checkPassword("secret123"));
    }
}

class VaultDoor {
    private int secretPin;

    public VaultDoor(int initialPin) {
        this.secretPin = initialPin;
    }

    private boolean isValidPin(int pin) {
        return this.secretPin == pin;
    }

    public boolean openDoor(int pin) {
        if (isValidPin(pin)) {
            System.out.println("Door Unlocked");
            return true;
        } else {
            System.out.println("Alarm Triggered");
            return false;
        }
    }
}

public class Main {
    public static void main(String[] args) {
        VaultDoor vault = new VaultDoor(9876);
        vault.openDoor(1111);
        vault.openDoor(9876);
    }
}

class SecurityOfficer {
    public String officerName;
    private String badgeId;
    private int clearanceLevel;

    public SecurityOfficer(String name, String badge, int clearance) {
        this.officerName = name;
        this.badgeId = badge;
        this.clearanceLevel = (clearance >= 1 && clearance <= 5) ? clearance : 1;
    }

    public boolean canAccessArea(int requiredLevel) {
        return this.clearanceLevel >= requiredLevel;
    }
}

public class Main {
    public static void main(String[] args) {
        SecurityOfficer alex = new SecurityOfficer("Alex", "SEC-402", 3);
        boolean highSec = alex.canAccessArea(4);
        boolean normalSec = alex.canAccessArea(2);
        System.out.println("Access granted: " + normalSec);
    }
}

