class PricingEngine {
    private double discountRate = 0.15;

    private double calculateDiscount(double price) {
        return price * discountRate;
    }

    public double getFinalPrice(double price) {
        return price - calculateDiscount(price);
    }
}

public class Main {
    public static void main(String[] args) {
        PricingEngine engine = new PricingEngine();
        System.out.println("Final price: $" + engine.getFinalPrice(100.0));
    }
}

class EncryptedMessage {
    private String rawText;
    private int cipherKey;

    public EncryptedMessage(String rawText, int key) {
        this.rawText = rawText;
        this.cipherKey = key;
    }

    private String encrypt() {
        StringBuilder sb = new StringBuilder();
        for (char c : rawText.toCharArray()) {
            sb.append((char) (c + cipherKey));
        }
        return sb.toString();
    }

    public String getEncryptedPayload() {
        return encrypt();
    }
}

public class Main {
    public static void main(String[] args) {
        EncryptedMessage msg = new EncryptedMessage("HELLO", 3);
        msg.getEncryptedPayload();
        System.out.println("Encrypted payload ready");
    }
}
